def my_tool(self, param: str, optional: Optional[int] = None) -> Dict[str, Any]:
    """Tool description.

    Args:
        param: Description
        optional: Optional param

    Returns:
        Dict with status or error
    """
    try:
        result = process(param)
        return {'status': 'success', 'data': result}
    except Exception as e:
        logger.error(f'Error: {e}')
        return {'error': str(e)}
